import csv,html,json
from pathlib import Path
with open('data/borough_complaints.csv',newline='') as f: rows=list(csv.DictReader(f))
options=''.join(f'<option>{html.escape(x)}</option>' for x in sorted({r['borough'] for r in rows}))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>NYC 311 complaint dashboard</title><style>body{font:16px system-ui;max-width:850px;margin:3rem auto;padding:1rem;color:#162432} .bar{background:#187b86;height:1.5rem} label{font-weight:bold} table{width:100%;border-collapse:collapse}td,th{padding:.6rem;text-align:left;border-bottom:1px solid #ddd} small{color:#555}</style><h1>NYC 311: leading complaints</h1><p>Requests created January 1, 2024. Counts represent reports, not verified incidents.</p><label>Borough <select id="borough">OPTIONS</select></label><table><thead><tr><th>Complaint</th><th>Requests</th><th>Share of borough requests</th></tr></thead><tbody id="result"></tbody></table><small>Source: NYC Open Data, 311 Service Requests. One-day snapshot; not a measure of need or service quality.</small><script>const rows=DATA;const select=document.querySelector('#borough');function show(){const body=document.querySelector('#result');body.replaceChildren();for(const r of rows.filter(r=>r.borough===select.value)){const tr=document.createElement('tr');for(const value of [r.complaint_type,r.requests,r.borough_pct+'%']){const td=document.createElement('td');td.textContent=value;tr.append(td)}body.append(tr)}}select.addEventListener('change',show);show()</script></html>'''.replace('OPTIONS',options).replace('DATA',json.dumps(rows).replace('</','<\\/'))
Path('dashboard.html').write_text(page)
